/**
 * A5 sample variable stars. Catalogue parameters (period, V range) are reference values;
 * the light-curve SHAPE comes from the illustrative template `templateMag` (synthetic), linearly
 * mapped onto the catalogue V range. Time series and noise are generated by the simulator.
 * Sources: AAVSO VSX / GCVS. TODO: cần xác minh từng giá trị với bản ghi VSX hiện hành trước khi phát hành.
 */
import type { VariableKind } from '../photometry/periodogram';

export interface VariableStarPreset {
  id: string;
  name: { vi: string; en: string };
  kind: VariableKind;
  /** Reference period P_ref [days]. */
  P: number;
  /** Catalogue V range: brightest and faintest magnitude. */
  vBright: number;
  vFaint: number;
  /** Intensity-mean ⟨V⟩ of the real star, when known (the synthetic curve is shifted to match it). */
  meanV?: number;
  catalog: string;
  /** Leavitt law applicable (classical Cepheid in the calibration sample class). */
  leavitt: boolean;
  /** Typical extinction A_V and an independent reference distance, if available. */
  AV?: number;
  refDistancePc?: { d: number; sigma: number; source: string };
}

